xecute([$it['variation_id'],$it['quantity'],$before,$after,$oid,$u['id']]);}}audit($pdo,$u['id'],'STATUS_CHANGE','orders',$oid,['status'=>$o['status']],['status'=>$st]);$pdo->commit();notify($pdo,$o['user_id'],'order','Status order berubah',"Order {$o['order_number']} sekarang {$st}.",'order',$oid);$msg='Status order diperbarui.';$vi=$pdo->prepare('SELECT variation_id FROM order_items WHERE order_id=?');$vi->execute([$oid]);es_fire_event($pdo,'order.status',['order'=>[$oid],'variation'=>array_map('intval',array_column($vi->fetchAll(),'variation_id'))],(int)$u['id']);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}
