 if($a==='task_status'){$tid=(int)$_POST['task_id'];$st=$_POST['status'];$s=$pdo->prepare('SELECT * FROM tasks WHERE id=?');$s->execute([$tid]);$t=$s->fetch();if(!$t||!in_array($st,['pending','in_progress','completed','cancelled'],true))$err='Task/status tidak valid.';elseif(!has_any(['manager','admin']) && $t['assignee_id']!=$u['id'] && $t['assigner_id']!=$u['id'])$err='Akses task ditolak.';else{$pdo->prepare('UPDATE tasks SET status=?,completed_at=? WHERE id=?')->execute([$st,$st==='completed'?date('Y-m-d H:i:s'):null,$tid]);$msg='Status task diperbarui.';}}
