 if($a==='approval'){$aid=(int)$_POST['approval_id'];$st=$_POST['status'];$comment=trim($_POST['comments']);$s=$pdo->prepare('SELECT a.*,d.title,d.owner_id FROM approvals a JOIN documents d ON d.id=a.document_id WHERE a.id=? AND a.approver_id=?');$s->execute([$aid,$u['id']]);$aRow=$s->fetch();if(!$aRow||!in_array($st,['approved','rejected'],true))$err='Approval tidak valid.';else{$newDoc=$st==='approved'?'approved':'archived';$pdo->beginTransaction();$pdo->prepare('UPDATE approvals SET status=?,comments=? WHERE id=?')->execute([$st,$comment?:null,$aid]);$pdo->prepare('UPDATE documents SET status=? WHERE id=?')->execute([$newDoc,$aRow['document_id']]);$pdo->commit();notify($pdo,$aRow['owner_id'],'approval','Approval selesai',"Dokumen {$aRow['title']} telah {$st}.",'document',$aRow['document_id']);$msg='Approval diproses.';}}
